// swift-tools-version: 5.9
import PackageDescription

/// Backstage, the mesh chat app for iOS.
///
/// The package is split so that the protocol can be tested without a device. `swift test`
/// on any Mac exercises the frame codec, the dedup filter and the relay rule against
/// fixtures generated by the Go reference; only `BackstageBLE` needs CoreBluetooth, and
/// only the app target needs Xcode.
///
/// That split is not tidiness. The radio is where debugging is slowest, and arriving
/// there with an already-verified protocol is the difference between one bug and an
/// indistinguishable pile of them.
let package = Package(
    name: "Backstage",
    platforms: [.iOS(.v16), .macOS(.v13)],
    products: [
        .library(name: "BackstageMesh", targets: ["BackstageMesh"]),
        .library(name: "BackstageCrypto", targets: ["BackstageCrypto"]),
    ],
    targets: [
        // Pure Swift, no CoreBluetooth, no UIKit. Runs anywhere Swift runs.
        .target(name: "BackstageMesh"),

        // CryptoKit for everything except the passphrase KDF. Argon2id is not in
        // CryptoKit and the channel keys have to match the box's byte for byte, so it is
        // implemented here against the RFC 9106 test vectors.
        .target(name: "BackstageCrypto", dependencies: ["BackstageMesh"]),

        .testTarget(name: "BackstageMeshTests", dependencies: ["BackstageMesh"]),
    ]
)
